struct D{n:*mut u32,w:u32}impl Drop for D{fn drop(&mut self){unsafe{*self.n+=self.w;}}}fn main(){let mut n=0u32;{let mut d=D{n:&raw mut n,w:1};let f:unsafe fn(*const D)->D=core::ptr::read::<D>;let g:unsafe fn(*mut D,D)=core::ptr::write::<D>;let q=unsafe{f(&raw const d)};unsafe{g(&raw mut d,D{n:&raw mut n,w:10});}check(n==0);let _=q;}check(n==11);}
